    static let truist: NSImage? = Data(base64Encoded: ConnectorIcon.truistPNG).flatMap { NSImage(data: $0) }
    static let bump: NSImage? = Data(base64Encoded: ConnectorIcon.bumpPNG).flatMap { NSImage(data: $0) }
