struct ConnectorIconView: View {
    let id: String
    /// The row's title: banks are told apart by it (American Express, Robinhood, Truist).
    var title: String = ""
    var size: CGFloat = 30

    private var bank: String? {
        guard self.id.hasPrefix("plaid:") else { return nil }
        let t = self.title.lowercased()
        if t.contains("american express") || t.contains("amex") { return "amex" }
        if t.contains("robinhood") { return "robinhood" }
        if t.contains("truist") { return "truist" }
        return "other"
    }

    private func tile(_ fill: Color) -> some View {
        RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous).fill(fill)
    }

    var body: some View {
        Group {
            if self.id == "bump", let image = ConnectorIcon.bump {
                Image(nsImage: image).resizable().interpolation(.high).scaledToFit()
            } else if self.id.hasPrefix("gmail:") {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous).fill(Color.white)
                    SVGPathShape(d: ConnectorIcon.gmailPath)
                        .fill(Color(red: 0.92, green: 0.26, blue: 0.21))
                        .frame(width: self.size * 0.62, height: self.size * 0.62)
                }
            } else if self.bank == "amex" {
                ZStack {
                    self.tile(.white)
                    SVGPathShape(d: ConnectorIcon.amexPath).fill(Color(red: 0.0, green: 0.44, blue: 0.81)).frame(width: self.size, height: self.size)
                }
            } else if self.bank == "robinhood" {
                ZStack {
                    self.tile(Color(red: 0.8, green: 1.0, blue: 0.0))
                    SVGPathShape(d: ConnectorIcon.robinhoodPath).fill(.black).frame(width: self.size * 0.6, height: self.size * 0.6)
                }
            } else if self.bank == "truist", let image = ConnectorIcon.truist {
                Image(nsImage: image).resizable().interpolation(.high).scaledToFit()
            } else if self.id == "github" {
                ZStack {
                    self.tile(Color(red: 0.14, green: 0.16, blue: 0.18))
                    SVGPathShape(d: BrandMarks.github).fill(.white).frame(width: self.size * 0.62, height: self.size * 0.62)
                }
            } else if self.id == "bookshelf", self.title.contains("Spotify") {
                ZStack {
                    self.tile(.black)
                    SVGPathShape(d: ConnectorIcon.spotifyPath).fill(Color(red: 0.11, green: 0.73, blue: 0.33)).frame(width: self.size * 0.72, height: self.size * 0.72)
                }
            } else if self.id == "bookshelf" {
                ZStack {
                    self.tile(Color(red: 0.98, green: 0.2, blue: 0.3))
                    Image(systemName: "music.note").font(.system(size: self.size * 0.5, weight: .bold)).foregroundStyle(.white)
                }
            } else if self.id.hasPrefix("plaid:") {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous)
                        .fill(LinearGradient(colors: [Color(red: 0.2, green: 0.55, blue: 0.95), Color(red: 0.1, green: 0.35, blue: 0.8)], startPoint: .top, endPoint: .bottom))
                    Image(systemName: "building.columns.fill").font(.system(size: self.size * 0.48)).foregroundStyle(.white)
                }
            } else if self.id.hasPrefix("perm:") {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous).fill(Color.gray.opacity(0.5))
                    Image(systemName: "lock.shield.fill").font(.system(size: self.size * 0.5)).foregroundStyle(.white)
                }
            } else if self.id == "messages" {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous)
                        .fill(LinearGradient(colors: [Color(red: 0.37, green: 0.9, blue: 0.4), Color(red: 0.05, green: 0.75, blue: 0.2)], startPoint: .top, endPoint: .bottom))
                    Image(systemName: "message.fill").font(.system(size: self.size * 0.5)).foregroundStyle(.white)
                }
            } else {
                ZStack {
                    RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous).fill(Color.white.opacity(0.12))
                    Image(systemName: "link").font(.system(size: self.size * 0.45)).foregroundStyle(.white.opacity(0.7))
                }
            }
        }
        .frame(width: self.size, height: self.size)
        .clipShape(RoundedRectangle(cornerRadius: self.size * 0.24, style: .continuous))
    }
}
